const money=n=>n==null||!Number.isFinite(Number(n))?'—':'₹'+Number(n).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2});
const state={role:'manager',module:'overview',page:'dashboard',filter:'All',query:'',connection:'online',range:'Today',basket:[],drafts:[],approvals:{},currentDetail:null,genericRecords:{},recordNotes:{},customer:'',nextSample:108};
