const moduleById=id=>MODULES.find(m=>m.id===id);
const badge=(text,tone)=>{const t=tone||(/quarantine|blocked|short|rejected|conflict/i.test(text)?'red':/pending|partial|transit|review|approval|draft/i.test(text)?'amber':/received|completed|approved|issued|posted|ready|matched|available|published|balanced/i.test(text)?'green':'blue');return `<span class="badge ${t}"><span class="dot"></span>${esc(text)}</span>`};
