let toastTimer;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500)}
function enhance(){document.querySelectorAll('[data-icon]').forEach(el=>{el.innerHTML=icon(el.dataset.icon);el.removeAttribute('data-icon')})}
function nav(){let last='';const category={overview:'Workspace',products:'Store operations',purchase:'Store operations',receiving:'Store operations',inventory:'Store operations',floor:'Store operations',sales:'Store operations',orders:'Store operations',finance:'Business management',customers:'Business management',production:'Business management',people:'Business management',operations:'Business management',reports:'Insights & controls',admin:'Insights & controls'};$('#nav').innerHTML=MODULES.filter(m=>roleAllowed(m)&&countPages(m)>0).map(m=>{let head='';if(category[m.id]!==last){last=category[m.id];head=`<div class="nav-label">${last}</div>`}return head+`<button class="nav-item ${state.module===m.id?'active':''}" data-go="${m.id}${m.id==='overview'?'/'+homeUrl().split('/')[1]:''}" ${state.module===m.id?'aria-current="page"':''}>${icon(m.icon)}<span>${esc(m.title)}</span>${m.id==='overview'?'<span class="nav-count">4</span>':''}</button>`}).join('');$('#side-role').textContent=roleNames[state.role];$('.avatar').textContent=state.role==='owner'?'OW':state.role==='manager'?'SM':roleNames[state.role].split(' ').map(v=>v[0]).join('');}
function navigate(url){let [m,p]=String(url||homeUrl()).split('/');if(m==='overview'&&p==='dashboard'&&!['owner','manager'].includes(state.role))p='my-work';let mod=moduleById(m),pg=mod?.pages.find(x=>x.id===p);if(!mod||(p&&!pg)||!roleAllowed(mod,pg)){toast('That page is unavailable in this role preview. Your workspace is shown instead.');[m,p]=homeUrl().split('/');mod=moduleById(m);pg=mod.pages.find(x=>x.id===p)}state.module=m;state.page=p||'';state.filter='All';state.query='';history.replaceState(null,'','#'+m+(p?'/'+p:''));$('#app').classList.remove('menu-open');$('#mobile-shade').classList.remove('visible');render();window.scrollTo({top:0,behavior:'instant'})}
function pageHead(title,description,actions='',eyebrow='SRE · MAIN STORE'){return `<div class="page-head"><div class="page-description"><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subtitle">${description}</p></div><div class="head-actions">${actions}</div></div>`}
function render(){nav();const m=moduleById(state.module),p=m.pages.find(p=>p.id===state.page);$('#crumbs').innerHTML=`<span>Workspace</span>${icon('chevron-right')}<button data-go="${m.id==='overview'?homeUrl():m.id}">${esc(m.title)}</button>${p&&m.id!=='overview'?icon('chevron-right')+`<strong>${esc(p.title)}</strong>`:m.id==='overview'?'<strong>/ Overview</strong>':''}`;let content;if(state.module==='overview'&&state.page==='dashboard')content=dashboard();else if(state.module==='overview'&&state.page==='my-work')content=myWork();else if(!state.page)content=moduleLanding(m);else if(!p)content=moduleLanding(m);else if(state.module==='purchase'&&state.page==='purchase-orders')content=purchase();else if(state.module==='receiving'&&['goods-receipts','quality-checks','quarantine'].includes(state.page))content=receiving(p);else if(state.module==='floor'&&['floor-indents','backstore-issue','floor-receiving'].includes(state.page))content=floor(p);else if(state.module==='inventory'&&['stock-on-hand','bins-putaway'].includes(state.page))content=inventory(p);else if(state.module==='products'&&state.page==='product-catalogue')content=inventory(p);else if(state.module==='sales'&&state.page==='point-of-sale')content=pos();else if(state.module==='finance'&&['cash-office','reconciliation','over-short-approval','day-close'].includes(state.page))content=finance(p);else if(state.module==='orders'&&state.page==='all-orders')content=orders(p);else if(state.module==='overview'&&state.page==='approval-inbox')content=approvals();else content=generic(m,p);$('#main').innerHTML=content;enhance();syncHeader()}
function myWork(){const targets={buyer:['purchase/purchase-orders','products/product-catalogue','purchase/supplier-invoices','purchase/quotation-comparison','products/data-quality','people/staff-tasks'],warehouse:['receiving/goods-receipts','inventory/bins-putaway','floor/backstore-issue','inventory/stock-counts','orders/picking-waves','people/staff-tasks'],floor:['floor/floor-indents','floor/floor-receiving','floor/refill-tasks','floor/shelf-counts','orders/picking-waves','people/staff-tasks'],cashier:['sales/point-of-sale','sales/returns-exchanges','sales/held-bills','sales/shift-close','orders/pickup-desk','people/daily-checklists'],finance:['finance/cash-office','finance/reconciliation','finance/supplier-payables','finance/day-close','purchase/supplier-invoices','finance/tally-bridge']}[state.role]||[];const pages=targets.map(url=>{const [mid,pid]=url.split('/'),m=moduleById(mid),p=m.pages.find(x=>x.id===pid);return {m,p,url}}).filter(x=>roleAllowed(x.m,x.p));return pageHead('My workspace','A focused workspace for the '+roleNames[state.role].toLowerCase()+'. Choose a task to explore.',button('Find a page','search',false,'search'))+`<div class="module-hero"><div><div class="eyebrow">${esc(roleNames[state.role].toUpperCase())} · ROLE PREVIEW</div><h2>Tasks and handovers</h2><p>These destinations reflect this role’s proposed access. All records are synthetic design examples.</p></div><div class="big-icon">${icon('clipboard-check')}</div></div><div class="section-top"><h2 class="section-title">Your daily tasks</h2><span class="section-subtitle">${pages.length} quick links</span></div><div class="module-grid">${pages.map(x=>workTile(x.p.title,x.p.description,x.p.icon,x.url,'Open task')).join('')}</div>`}
function miniBars(){return '<span class="mini-bars">'+[35,54,45,70,55,84,100,86].map(h=>`<i style="height:${h}%"></i>`).join('')+'</span>'}
function kpi(title,value,ico,sub,trend){return `<div class="kpi"><div class="kpi-top"><span>${title}</span>${icon(ico)}</div><div class="kpi-value">${value}</div><div class="kpi-bottom"><span>${trend?`<span class="kpi-trend">${icon('trending-up')}${trend}</span> <span>${sub}</span>`:sub}</span>${miniBars()}</div></div>`}
function workTile(title,desc,ico,url,caption='Open workspace'){return `<button class="work-tile" data-go="${url}"><div class="tile-top"><span class="tile-icon">${icon(ico)}</span><span class="tile-arrow">${icon('arrow-up-right')}</span></div><strong>${title}</strong><small>${desc}</small><span class="count-label">${caption}</span></button>`}
function dashboard(){const factor=state.range==='Today'?1:state.range==='This week'?6.3:23.8;let tiles=[['Purchase','Orders, suppliers & buying','shopping-bag','purchase','6 open orders'],['Receiving & QC','Deliveries, checks & putaway','package-check','receiving','8 deliveries today'],['Stock & backstore','Stock, bins & movement','boxes','inventory','24 items to review'],['Floor & indents','Request, issue & receive','arrow-left-right','floor','12 open requests'],['Sales & returns','Billing, exchanges & refunds','scan-line','sales','3 tills trading'],['Cash & accounts','Reconcile, close & report','wallet','finance','2 shifts to close']];tiles=tiles.filter(t=>roleAllowed(moduleById(t[3])));if(tiles.length<3){tiles=MODULES.filter(m=>m.id!=='overview'&&roleAllowed(m)).slice(0,6).map(m=>[m.title,m.description,m.icon,m.id,countPages(m)+' subpages'])}return pageHead('Store overview',`Operational snapshot · ${state.range.toLowerCase()}`,button(state.range+' · 4 Oct 2026','date',false,'calendar-days')+goButton('Review approvals','overview/approval-inbox',true,'check-check'),'SUNDAY, 4 OCTOBER 2026')+`<div class="kpi-grid">${kpi('Net sales '+state.range.toLowerCase(),money(184650*factor),'shopping-basket','vs previous period','8.4%')}${kpi('Purchase commitments',money(86400*factor),'receipt-text','6 open purchase orders')}${kpi('Floor requests','12','arrow-left-right','4 awaiting your approval')}${kpi('Stock availability','98.2%','package-check','24 products need attention')}</div><div class="dashboard-columns"><div class="left-column"><section class="panel"><div class="panel-header"><div><h2 class="panel-title">From purchase to the shelf</h2><div class="panel-desc">Follow the stock. Every handover stays visible.</div></div><button class="text-link" data-go="inventory/stock-ledger">View movement ${icon('arrow-right')}</button></div><div class="panel-body"><div class="journey">${[['Purchase','6 open','purchase/purchase-orders'],['Receive','8 due','receiving/goods-receipts'],['Backstore','3 putaways','inventory/bins-putaway'],['Indent','12 open','floor/floor-indents'],['Floor','5 to receive','floor/floor-receiving'],['Sell','3 tills','sales/point-of-sale']].map((x,i)=>`<button data-go="${x[2]}"><span class="journey-num">${i+1}</span><b>${x[0]}</b><small>${x[1]}</small></button>`).join('')}</div><div class="flow-footer">${icon('circle-check')} Separate approval, issue and receipt. Stock arrives on the floor only after receipt.</div></div></section><div class="section-top"><h2 class="section-title">Your workspaces</h2><button class="text-link" data-action="page-map">All modules ${icon('arrow-up-right')}</button></div><div class="work-grid">${tiles.map(t=>workTile(...t)).join('')}</div></div><div class="right-column"><section class="panel"><div class="panel-header"><h2 class="panel-title">Needs your attention</h2>${badge('4 actions','amber')}</div><div class="attention-list">${attention('4 floor requests to approve','Grocery & personal care · 48 units requested','clipboard-check','floor/floor-indents','')}${attention('Fresh produce needs a QC decision','GRN-0862 · 8 crates held for review','package-search','receiving/quality-checks','red')}${attention('Till 02 is short by ₹50.00','A counted variance is waiting for sign-off.','wallet','finance/over-short-approval','')}${attention('6 items are near expiry','Review the batches before the next refill.','calendar-clock','inventory/expiry-recalls','green')}</div><div class="attention-footer"><span>Ordered by what needs action</span><button class="text-link" data-go="overview/exceptions">View all ${icon('arrow-right')}</button></div></section><section class="cash-panel">${icon('sunset')}<div class="eyebrow">CASH & DAY CLOSE</div><strong>Cash reconciliation</strong><p>Review till counts, cash pickups and settlement differences in one place.</p>${goButton('Open cash office','finance/cash-office',false,'arrow-right')}</section></div></div><section class="panel" style="margin-top:23px"><div class="panel-header"><div><h2 class="panel-title">Today’s purchase activity</h2><div class="panel-desc">Sample activity · amounts include the purchase commitment</div></div><button class="text-link" data-go="purchase/purchase-orders">View purchase orders ${icon('arrow-up-right')}</button></div>${poTable(PO.slice(0,3))}</section><div class="day-band">${icon('shield-check')}<span>Changes carry a named owner, an approval trail and a clear sync status.</span><button class="text-link" data-action="sync">Connection details ${icon('arrow-right')}</button></div>`}
function attention(title,sub,ico,url,tone){return `<button class="attention-item" data-go="${url}"><span class="attention-symbol ${tone}">${icon(ico)}</span><span class="attention-copy"><strong>${title}</strong><small>${sub}</small></span>${icon('chevron-right')}</button>`}
function moduleLanding(m){const pages=m.pages.filter(p=>roleAllowed(m,p));return pageHead(m.title,m.description,button('Find a page','search',false,'search'))+`<div class="module-hero"><div><div class="eyebrow">ONE WORKSPACE · ${pages.length} SUBPAGES</div><h2>${moduleTagline(m.id)}</h2><p>Open a task below. Registers, related documents and approval history stay together as you work.</p></div><div class="big-icon">${icon(m.icon)}</div></div><div class="section-top"><h2 class="section-title">Pages & tools</h2><span class="section-subtitle">Choose a task to continue</span></div><div class="module-grid">${pages.map(p=>`<button class="work-tile" data-go="${m.id}/${p.id}"><div class="tile-top"><span class="tile-icon">${icon(p.icon)}</span><span class="tile-arrow">${icon('arrow-up-right')}</span></div><strong>${esc(p.title)}</strong><small>${esc(p.description)}</small><span class="tile-caption"><span>${p.type==='report'?'Insights & analysis':p.type==='settings'?'Configuration':'Records & actions'}</span>${icon('chevron-right')}</span></button>`).join('')}</div>`}
function moduleTagline(id){return {purchase:'Buy with the full picture.',receiving:'Receive accurately. Release with confidence.',inventory:'Know what you have. Know where it is.',floor:'The right item, on the right shelf.',sales:'A smooth checkout, every time.',finance:'From till count to a balanced day.',products:'One trusted catalogue for your whole store.',orders:'One order. Every step accounted for.',customers:'Build lasting customer relationships.',production:'Turn ingredients into traceable finished goods.',people:'Help your team do their best work.',operations:'Keep the store ready for the day.',reports:'Find the numbers behind every decision.',admin:'The right access. The right controls.',overview:'Start with what matters today.'}[id]}
function summary(items){return `<div class="summary-strip">${items.map(([label,value])=>`<div class="summary-item"><span>${label}</span><strong>${value}</strong></div>`).join('')}</div>`}
function toolbar(filters,placeholder='Search this register…'){return `<div class="toolbar"><div class="filters">${filters.map(f=>`<button class="filter ${state.filter===f?'selected':''}" data-filter="${f}" aria-pressed="${state.filter===f}">${f}</button>`).join('')}</div><label class="field-search">${icon('search')}<input id="register-search" aria-label="Search register" placeholder="${placeholder}" value="${esc(state.query)}"></label></div>`}
function filtered(rows){const norm=v=>String(v||'').toLowerCase().split(' · ')[0].trim();return rows.filter(r=>{const status=norm(r.status),f=norm(state.filter);const match=f==='all'||f==='open'?!['received','completed','balanced','rejected','closed'].includes(status)||f==='all':status===f;return match&&JSON.stringify(r).toLowerCase().includes(state.query.toLowerCase())})}
function table(headers,rows){return `<div class="table-wrap"><table class="data-table"><thead><tr>${headers.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>'<tr>'+r.map(c=>'<td>'+c+'</td>').join('')+'</tr>').join(''):`<tr><td colspan="${headers.length}"><div class="empty-state">${icon('search-x')}<h3>No matching records</h3>Try another status or search term.</div></td></tr>`}</tbody></table></div>`}
function tableFooter(n){return `<div class="table-footer"><span>${n} sample records · Main store</span><button class="text-link" data-action="export">Export register ${icon('download')}</button></div>`}
function rowLink(kind,r){return `<button class="row-btn" data-detail="${kind}:${r.id}">${r.id}</button><small>${r.date||'Updated today'}</small>`}
function poTable(rows){return table(['Purchase order','Supplier','Commitment','Status',''],rows.map(r=>[rowLink('po',r),`<strong>${esc(r.name)}</strong><small>${esc(r.sub)}</small>`,money(r.amount),badge(r.status),`<button class="icon-btn" data-detail="po:${r.id}" aria-label="Open ${r.id}">${icon('chevron-right')}</button>`]))}
function purchase(){const rows=filtered(PO);return pageHead('Purchase orders','Plan, approve and track every supplier commitment.',button('Export','export',false,'download')+button('New purchase order','create-po',true))+summary([['Open commitments',money(99850)],['Awaiting approval','1'],['Expected today','3 deliveries'],['Partially received','1 order']])+`<section class="panel">${toolbar(['All','Pending approval','Issued','Partially received','Received','Draft'],'Order or supplier…')}${poTable(rows)}${tableFooter(rows.length)}</section><div class="day-band">${icon('git-compare-arrows')}Every receipt stays linked to its purchase order and remaining quantity.<button class="text-link" data-go="receiving/three-way-match">Three-way matching ${icon('arrow-right')}</button></div>`}
function receiving(p){let rows=filtered(GRN);if(p.id==='quarantine')rows=rows.filter(r=>r.status==='Quarantine');return pageHead(p.title,'Check quantity, condition and traceability before stock becomes available.',button('Receive delivery','receive',true,'package-plus'))+summary([['Expected deliveries','8'],['Received today','4'],['Waiting for QC','2 receipts'],['Held stock','8 crates / 12 packs']])+`<div class="hint-panel">${icon('shield-alert')}<div><strong>Held stock stays unavailable for sale.</strong><p>Record the discrepancy and request an independent quality decision. Approval and putaway are separate steps.</p></div></div><section class="panel"><div class="status-track">${['Expected','Receiving','QC decision','Putaway','Completed'].map((s,i)=>`<span class="${i<2?'done':i===2?'current':''}">${icon(i<2?'circle-check':'circle')} ${s}${i<4?icon('chevron-right'):''}</span>`).join('')}</div>${toolbar(['All','QC review','Quarantine','Completed'],'Receipt, PO or supplier…')}${table(['Receipt','Supplier / arrival','Ordered','Counted','Status',''],rows.map(r=>[rowLink('grn',r),`<strong>${esc(r.name)}</strong><small>${esc(r.sub)}</small>`,r.ordered,r.received,badge(r.status),`<button class="text-link" data-detail="grn:${r.id}">Review ${icon('arrow-right')}</button>`]))}${tableFooter(rows.length)}</section>`}
