function sampleValue(field,i,m,p){const f=field.toLowerCase();if(/status|decision/.test(f))return badge(['Draft','Pending review','Completed'][i%3]);if(/date|day|period|updated|due|time/.test(f))return ['4 Oct 2026','4 Oct 2026','3 Oct 2026'][i%3];if(/amount|value|cost|price|balance|sales|payable|cash|variance|profit|margin|liability/.test(f))return money([2480,6800,1450][i%3]);if(/quantity|qty|stock|count|units/.test(f))return [24,48,12][i%3]+' units';if(/owner|staff|person|employee|user|raised|approved|assignee/.test(f))return ['Demo manager','Demo buyer','Demo supervisor'][i%3];if(/supplier/.test(f))return ['Kaveri Grocery','Fresh Valley','Greenleaf Dairy'][i%3];if(/customer|account/.test(f))return 'Demo account '+String(i+1).padStart(2,'0');if(/branch|store|location/.test(f))return 'Main store';if(/product|item|sku/.test(f))return STOCK[i%6].name;if(/reason|note|description|evidence/.test(f))return ['Routine review','Supporting record attached','Awaiting independent check'][i%3];if(/permission|role/.test(f))return ['Store manager','Buyer','Accounts'][i%3];if(/temperature|limit/.test(f))return ['Needs classification','Configured per product','Review required'][i%3];if(/id|number|reference|code/.test(f))return 'DEMO-'+String(104+i);return ['Sample '+field.toLowerCase(),'Review '+field.toLowerCase(),'Recorded '+field.toLowerCase()][i%3]}
