function showDetail(kind,id){if(kind==='generic'){genericDetail(id);return}const data={po:PO,grn:GRN,indent:INDENTS,stock:STOCK,order:ORDERS,cash:CASH};let r=data[kind]?.find(x=>x.id===id);const m=moduleById(state.module),p=m.pages.find(p=>p.id===state.page);if(!r)r={id:'DEMO-'+(104+Number(id)),name:p?.title||'Sample record',status:'Pending review',sub:m.title,role:'buyer',amount:2480};state.currentDetail={kind,id,record:r};let fields=[];if(kind==='stock')fields=[['Backstore',r.back+' units'],['Floor stock',r.floor+' units'],['Held stock',r.held+' units'],['Bin',r.bin],['Selling price',money(r.amount)],['Source','Sample catalogue']];else if(kind==='indent')fields=[['Requested',r.requested],['Issued',r.issued],['Received',r.received],['Priority',r.priority],['Raised by',roleNames[r.role]],['Destination',r.name]];else if(kind==='cash')fields=[['Expected cash',money(r.expected)],['Counted cash',r.counted==null?'Not counted':money(r.counted)],['Difference',r.counted==null?'Awaiting count':money(r.counted-r.expected)],['Cashier',r.name]];else fields=[['Supplier / customer',r.name],['Store','SRE · Main store'],['Raised by',roleNames[r.role]||'Demo user'],['Value',money(r.amount)],['Created',r.date||'4 Oct 2026'],['Sync state',r.date==='Just now'?'Preview draft · not sent':'Illustrative posted state']];const own=r.role===state.role;let action='';if(/approval|review/.test(r.status)&&['owner','manager','finance'].includes(state.role)&&!own)action=button('Review decision','approve',true,'check-check');else if(own&&/approval|review/.test(r.status))action='<span class="form-hint">A different authorised person must approve this request.</span>';else action=button('Add a note','add-note',true,'message-square-plus');$('#detail-content').innerHTML=`<div class="dialog-head"><div><div class="eyebrow">${kind==='po'?'PURCHASE ORDER':kind==='indent'?'FLOOR INDENT':kind==='stock'?'STOCK RECORD':'RECORD DETAILS'}</div><h2>${esc(r.id)}</h2><p>${esc(r.sub||r.name)}</p></div><button class="icon-btn" data-action="close-detail" aria-label="Close record">${icon('x')}</button></div><div class="dialog-content">${badge(r.status)}<div class="detail-grid">${fields.map(([k,v])=>`<div class="detail-field"><span>${k}</span><strong>${esc(v)}</strong></div>`).join('')}</div>${r.items?`<h3>Order lines</h3>${table(['Product','Quantity','Value'],r.items.map(x=>[x[0],x[1],money(x[3])]))}`:''}<div class="detail-note ${kind==='indent'?'amber':''}">${kind==='indent'?'An issue moves stock into transit. An independent floor receipt records the actual arrival.':kind==='grn'?'Release of quarantined stock requires a separate quality decision. Held stock is not sellable.':kind==='cash'?'A variance needs a recorded reason and the correct sign-off authority.':kind==='order'?'Partial delivery and payment differences remain explicit throughout reconciliation.':'This is a sample record. The prototype does not send transactions to your ERP.'}</div>${noteList(kind,id)}<h3>Illustrative activity trail</h3><ol class="timeline"><li><strong>Record created</strong><span>Demo ${r.role||'staff'} · 9:10 am</span></li><li><strong>Example: local save</strong><span>Illustrative event · no ERP transaction</span></li><li><strong>Example: head-office acknowledgement</strong><span>Illustrative event · current sample status: ${esc(r.status)}</span></li></ol><h3>Related records</h3><button class="text-link" data-go="${kind==='po'?'receiving/goods-receipts':kind==='indent'?'inventory/stock-ledger':kind==='order'?'orders/delivery-reconciliation':'overview/approval-inbox'}">${icon('link-2')} ${kind==='po'?'View linked goods receipts':kind==='indent'?'View stock movements':kind==='order'?'View delivery reconciliation':'Open approval inbox'} ${icon('arrow-right')}</button></div><div class="dialog-actions">${button('Close','close-detail',false,'x')}${action}</div>`;if(!$('#detail-dialog').open)$('#detail-dialog').showModal()}
function formField(label,name,type='text',value='',full=false,options={}){const constraints=type==='number'?`min="${options.min??0}" step="${options.step??0.01}" ${options.max!=null?`max="${options.max}"`:''}`:'';return `<label class="${full?'full':''}">${esc(label)}<input name="${esc(name)}" type="${type}" value="${esc(value)}" ${constraints} required></label>`}
function genericForm(){const m=moduleById(state.module),p=m.pages.find(x=>x.id===state.page);openModal('Add sample · '+p.title,`<form id="generic-form"><div class="form-grid">${p.fields.map((field,i)=>formField(field,'field-'+i,'text',/status|decision|assignment state/i.test(field)?'Draft':'',i===0)).join('')}</div><p class="form-hint">This adds a visible draft to this page’s layout preview. It does not assign staff, post stock or approve a transaction. Drafts disappear when the page is reloaded.</p></form>`,button('Cancel','close-modal',false,'x')+'<button class="btn primary" form="generic-form" type="submit">Add to sample register</button>')}
function createForm(type){if(type==='new-generic'){genericForm();return}const map={'create-po':['New purchase order','Supplier','supplier','Kaveri Grocery Distributors'],'receive':['Receive a delivery','Supplier / purchase order','supplier','PO-1047 · Fresh Valley Produce'],'raise-indent':['Raise a floor indent','Department / aisle','supplier','Grocery · Aisle 03'],'new-generic':['New '+(moduleById(state.module).pages.find(p=>p.id===state.page)?.title.toLowerCase()||'record'),'Record name','supplier','']};const [title,label,name,val]=map[type];openModal(title,`<form id="record-form" data-form="${type}"><div class="form-grid">${formField(label,name,'text',val,true)}${formField('Product / item','product','text','Ponni rice · 1 kg',true)}${formField('Quantity (units)','quantity','number','24',false,{min:1,step:1})}${formField(type==='create-po'?'Unit cost (₹)':'Reference','cost',type==='create-po'?'number':'text',type==='create-po'?'60':'Demo record')}<label class="full">Reason / notes<textarea name="notes" required placeholder="Add the reason for this request"></textarea></label></div><p class="form-hint">The draft is added to this preview only. Required approval stays separate from record creation.</p><div class="form-errors" id="form-errors" role="alert"></div></form>`,button('Cancel','close-modal',false,'x')+`<button class="btn primary" type="submit" form="record-form">${icon('save')} Save draft</button>`)}
function pageMap(){const count=MODULES.reduce((a,m)=>a+m.pages.length,0);openModal('The complete ERP page map',`<p class="subtitle" style="margin:0 0 20px">${MODULES.length} work areas · ${count} proposed page destinations. This is the design hierarchy, not an implementation-completion score. Restricted destinations indicate the required role preview.</p><div class="map-grid">${MODULES.map(m=>`<section class="map-group"><h3>${icon(m.icon)} ${m.title}</h3><small>${m.pages.length} SUBPAGES</small>${m.pages.map(p=>`<button data-go="${m.id}/${p.id}" ${!roleAllowed(m,p)?'disabled':''}>${esc(p.title)}${!roleAllowed(m,p)?' · Role restricted':''}</button>`).join('')}</section>`).join('')}</div>`,'',true)}
function syncHeader(){const mode=state.connection;$('#sync-indicator').innerHTML=`<span class="dot ${mode!=='online'?'amber':''}"></span> ${mode==='online'?'Online · 0 unsent':mode==='offline'?'Offline · 3 unsent':'Conflict · 1 needs review'} <span class="sync-time">${mode==='online'?'Last synced just now':'Last synced 10:32 am'}</span>${icon('chevron-right')}`}
function syncDialog(){openModal('Connection & sync',`<div class="detail-note">Preview how the store interface communicates saved, queued and conflicting changes. This control only simulates connection states.</div>${[['online','Online','All sample changes posted at head office.'],['offline','Offline','3 sample changes saved on this device, waiting to send.'],['conflict','Needs review','1 sample record needs a decision before it can be posted.']].map(([v,t,d])=>`<label class="connection-option"><input type="radio" name="connection" value="${v}" ${state.connection===v?'checked':''}><span><strong>${t}</strong><small style="display:block;color:var(--muted);font-size:10px;margin-top:5px">${d}</small></span></label>`).join('')}`,button('Apply preview state','apply-sync',true,'refresh-cw'))}
function searchDialog(){openModal('Find your next task',`<div class="search-box">${icon('search')}<input id="global-search" aria-label="Search all pages" placeholder="Try purchase, expiry, returns or payroll…" autofocus></div><div class="search-results" id="search-results"></div>`);searchResults('');setTimeout(()=>$('#global-search')?.focus(),20)}
function searchResults(q){const ps=allPages().filter(p=>p.allowed&&(p.title+' '+p.description+' '+p.moduleTitle).toLowerCase().includes(q.toLowerCase())).slice(0,20);$('#search-results').innerHTML=ps.length?ps.map(p=>`<button class="search-result" data-go="${p.module}/${p.id}">${icon(p.icon)}<span><strong>${esc(p.title)}</strong><small>${esc(p.moduleTitle)} · ${p.type}</small></span>${icon('arrow-up-right')}</button>`).join(''):'<div class="empty-state">No pages match this search in your current role preview.</div>'}
function exportCSV(){const m=moduleById(state.module),p=m.pages.find(p=>p.id===state.page);let data;if(state.module==='purchase'&&state.page==='purchase-orders')data=[['Order','Supplier','Amount INR','Status'],...filtered(PO).map(r=>[r.id,r.name,r.amount,r.status])];else if(state.page==='stock-on-hand'||state.page==='product-catalogue'||state.page==='bins-putaway')data=[['Product','Backstore units','Floor units','Held units'],...filtered(STOCK).map(r=>[r.name,r.back,r.floor,r.held])];else if(state.module==='receiving'&&['goods-receipts','quality-checks','quarantine'].includes(state.page))data=[['Receipt','Supplier','Ordered','Counted','Status'],...filtered(GRN).filter(r=>state.page!=='quarantine'||r.status==='Quarantine').map(r=>[r.id,r.name,r.ordered,r.received,r.status])];else if(state.module==='floor'&&['floor-indents','backstore-issue','floor-receiving'].includes(state.page))data=[['Indent','Department','Requested','Issued','Received','Status'],...filtered(INDENTS).map(r=>[r.id,r.name,r.requested,r.issued,r.received,r.status])];else if(state.module==='finance'&&['cash-office','reconciliation','over-short-approval','day-close'].includes(state.page))data=[['Shift','Cashier','Expected INR','Counted INR','Status'],...filtered(CASH).map(r=>[r.id,r.name,r.expected,r.counted??'Awaiting count',r.status])];else if(state.module==='orders'&&state.page==='all-orders')data=[['Order','Customer','Value INR','Status'],...filtered(ORDERS).map(r=>[r.id,r.name,r.amount,r.status])];else if(p)data=[p.fields,...filtered(genericRecords(m,p)).map(r=>p.fields.map(f=>r.values[f]||''))];else data=[['Workspace','Preview'],[m.title,'Sample page map']];const csv=data.map(row=>row.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\r\n');const u=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download='SRE-'+state.module+'-'+(state.page||'workspace')+'-sample.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),100);toast('Sample data exported; no live ERP records are included.')}
document.addEventListener('click',e=>{const go=e.target.closest('[data-go]');if(go){if(go.disabled)return;$('#modal').close();$('#detail-dialog').close();navigate(go.dataset.go);return}const detail=e.target.closest('[data-detail]');if(detail){const [k,id]=detail.dataset.detail.split(':');showDetail(k,id);return}const filt=e.target.closest('[data-filter]');if(filt){state.filter=filt.dataset.filter;render();return}const el=e.target.closest('[data-action]');if(!el)return;const action=el.dataset.action;switch(action){case'menu':$('#app').classList.toggle('menu-open');$('#mobile-shade').classList.toggle('visible');break;case'page-map':pageMap();break;case'search':searchDialog();break;case'close-modal':$('#modal').close();break;case'close-detail':$('#detail-dialog').close();break;case'sync':syncDialog();break;case'apply-sync':state.connection=document.querySelector('input[name=connection]:checked').value;syncHeader();$('#modal').close();toast('Connection state changed in the preview.');break;case'export':exportCSV();break;case'date':openModal('Reporting period',`<div class="action-stack">${['Today','This week','This month'].map(d=>`<button class="btn ${state.range===d?'primary':''}" data-action="range" data-range="${d}">${d}</button>`).join('')}</div>`);break;case'range':state.range=el.dataset.range;$('#modal').close();render();break;case'create-po':case'receive':case'raise-indent':case'new-generic':createForm(action);break;case'notifications':openModal('Your notifications',`<div class="attention-list">${attention('4 requests are waiting for review','Floor indents · Grocery & personal care','clipboard-check','overview/approval-inbox','')}${attention('A goods receipt needs a QC decision','8 crates remain held','package-search','receiving/quality-checks','red')}${attention('One till count needs sign-off','Till 02 · ₹50.00 shortage','wallet','finance/cash-office','')}</div>`);break;case'help':openModal('A guide for every role',`<div class="action-stack">${goButton('Opening & closing checklists','people/daily-checklists',false,'list-checks')}${goButton('Training & standard procedures','people/training-sop',false,'book-open')}${goButton('Browse the store workflow','overview/dashboard',false,'route')}</div><p class="form-hint">Keyboard: Ctrl / ⌘ + K to search · Escape to close a panel.</p>`);break;case'stock-search':$('#register-search')?.focus();toast('Search by product, barcode or backstore bin.');break;case'approve':{const r=state.currentDetail?.record;if(r.role===state.role){toast('A different authorised person must approve.');break}openModal('Review this request',`<div class="detail-note">${esc(r.id)} · ${esc(r.name)}<br>Approval allows the next step. It does not receive stock or make a payment.</div><form id="approval-form"><div class="form-grid" style="margin-top:18px"><label class="full">Decision<select name="decision"><option>Approved</option><option>Rejected</option></select></label><label class="full">Decision reason<textarea name="reason" required></textarea></label></div></form>`,button('Cancel','close-modal',false,'x')+'<button class="btn primary" form="approval-form" type="submit">Confirm decision</button>');break}case'add-note':openModal('Add a record note',`<form id="note-form"><div class="form-grid"><label class="full">Your note<textarea name="note" required></textarea></label></div></form>`,button('Cancel','close-modal',false,'x')+'<button class="btn primary" type="submit" form="note-form">Save note</button>');break;case'floor-count':if(INDENTS.find(r=>r.id==='IND-0247')?.receiptRecorded){toast('This sample handover already has a receipt.');break}if(!['owner','floor'].includes(state.role)){openModal('Floor receipt needs a different person','<div class="detail-note amber">Switch to the Floor team role preview to count this receipt. The issuer cannot receive their own stock movement.</div>');break}openModal('Count the floor receipt',`<div class="detail-note">IND-0247 · 36 units issued to Personal care, Aisle 07.</div><form id="floor-form" style="margin-top:18px"><div class="form-grid">${formField('Units received','units','number','36',false,{min:0,step:1,max:36})}<label>Condition<select name="condition"><option>Good condition</option><option>Damage found</option></select></label><label class="full">Discrepancy / notes<textarea name="reason"></textarea></label></div></form>`,button('Cancel','close-modal',false,'x')+'<button class="btn primary" type="submit" form="floor-form">Confirm sample receipt</button>');break;case'pos-add':{const p=STOCK.find(r=>r.id===el.dataset.id),r=state.basket.find(x=>x.id===p.id);if(r)r.qty++;else state.basket.push({...p,qty:1});render();break}case'pos-minus':{const p=state.basket.find(r=>r.id===el.dataset.id);if(p&&--p.qty<=0)state.basket=state.basket.filter(r=>r.id!==p.id);render();break}case'pos-category':{document.querySelectorAll('[data-action=pos-category]').forEach(x=>x.classList.toggle('selected',x===el));$('#product-grid').innerHTML=productsHtml(el.dataset.cat==='All'?STOCK:STOCK.filter(r=>(r.sub+' '+r.name).includes(el.dataset.cat)));break}case'new-bill':if(state.basket.length)openModal('Start another bill?','<p class="subtitle">The current practice basket will be cleared.</p>',button('Keep this bill','close-modal',false,'x')+button('Clear practice basket','clear-basket',true,'plus'));else toast('Ready for a new practice bill.');break;case'clear-basket':state.basket=[];state.customer='';$('#modal').close();render();break;case'pos-pay':{const total=state.basket.reduce((a,r)=>a+r.qty*r.amount,0);openModal('Cash payment',`<div class="basket-total"><span>Amount due</span><span>${money(total)}</span></div><form id="payment-form"><div class="form-grid">${formField('Cash received (₹)','cash','number',Math.ceil(total).toString(),true)}</div><p class="form-hint">This is a practice transaction. No real payment is processed.</p><div class="form-errors" id="payment-error" role="alert"></div></form>`,button('Back to bill','close-modal',false,'arrow-left')+'<button class="btn primary" form="payment-form" type="submit">Complete practice sale</button>');break}case'held':openModal('Held bills','<div class="empty-state">'+icon('pause')+'<h3>No held bills in this practice session</h3>The active basket remains available when you close this panel.</div>');break;case'customer':openModal('Add a customer',`<form id="customer-form"><div class="form-grid">${formField('Demo customer name','name','text','Demo customer',true)}</div></form>`,button('Cancel','close-modal',false,'x')+'<button class="btn primary" form="customer-form" type="submit">Use sample customer</button>');break;case'cash-count':openModal('Submit a blind cash count',`<p class="subtitle" style="margin-bottom:18px">SHIFT-0106 · Till 03. Enter the actual count without seeing an expected figure.</p><form id="cash-form"><div class="form-grid">${formField('Cash counted (₹)','count','number','',true)}<label class="full">Count notes<textarea name="note" required></textarea></label></div></form>`,button('Cancel','close-modal',false,'x')+'<button class="btn primary" type="submit" form="cash-form">Submit sample count</button>');break;case'close-day':openModal('Day-close checklist',`<div class="stat-list"><div>Sales and returns posted ${badge('Matched')}</div><div>All till counts submitted ${badge('1 pending','amber')}</div><div>Differences signed off ${badge('₹50.00 pending','amber')}</div><div>Card / UPI settlements ${badge('Review','amber')}</div></div><div class="detail-note amber">Day close remains pending while these items are unresolved.</div>`);break;case'save-settings':openModal('Preference layout preview','<div class="detail-note">These controls illustrate the proposed settings page. They are not saved or applied to the ERP. Use the page map to continue reviewing the design.</div>',button('Continue reviewing','close-modal',true,'check'));break}});
document.addEventListener('input',e=>{if(e.target.id==='global-search')searchResults(e.target.value);if(e.target.id==='register-search'){const n=e.target.selectionStart;state.query=e.target.value;render();const i=$('#register-search');i?.focus();i?.setSelectionRange(n,n)}if(e.target.id==='pos-search')$('#product-grid').innerHTML=productsHtml(STOCK.filter(r=>(r.name+' '+r.sub).toLowerCase().includes(e.target.value.toLowerCase())))});
document.addEventListener('change',e=>{if(e.target.id==='role'){state.role=e.target.value;state.basket=[];state.customer='';navigate(homeUrl());toast('Showing the '+roleNames[state.role].toLowerCase()+' design preview.')}});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target;if(!f.reportValidity())return;const d=Object.fromEntries(new FormData(f));if(f.id==='generic-form'){const m=moduleById(state.module),p=m.pages.find(x=>x.id===state.page),values=Object.fromEntries(p.fields.map((field,i)=>[field,d['field-'+i]||'']));for(const field of p.fields)if(/status|decision|assignment state/i.test(field))values[field]='Draft';const r={id:'LOCAL-'+state.nextSample++,name:p.title,status:'Draft',role:state.role,values};genericRecords(m,p).unshift(r);$('#modal').close();state.filter='All';state.query='';render();toast(r.id+' added to this page’s sample register.');}else if(f.id==='record-form'){const type=f.dataset.form,n=Number(d.quantity);if(!Number.isFinite(n)||n<1)return;const r={id:type==='create-po'?'PO-'+(1049+state.drafts.length):type==='raise-indent'?'IND-'+(249+state.drafts.length):type==='receive'?'GRN-'+(863+state.drafts.length):'DEMO-'+(100+state.drafts.length),name:d.supplier,sub:d.product+' · '+n+' units',date:'Just now',amount:type==='create-po'?n*Number(d.cost):undefined,status:'Draft',role:state.role,requested:n+' units',issued:'—',received:'—',priority:'Normal',ordered:n+' units'};state.drafts.push(r);if(type==='create-po'){PO.unshift(r);state.module='purchase';state.page='purchase-orders'}if(type==='raise-indent'){INDENTS.unshift(r);state.module='floor';state.page='floor-indents'}if(type==='receive'){GRN.unshift(r);r.received='0 units';state.module='receiving';state.page='goods-receipts'}$('#modal').close();state.filter='All';state.query='';history.replaceState(null,'','#'+state.module+'/'+state.page);render();toast(r.id+' saved as a sample draft.');}else if(f.id==='approval-form'){state.currentDetail.record.status=d.decision;$('#modal').close();$('#detail-dialog').close();render();toast('Sample decision recorded: '+d.decision.toLowerCase()+'.');}else if(f.id==='floor-form'){const n=Number(d.units);if(n>36||n<0){toast('Count must be between 0 and the 36 units issued.');return}if((n<36||d.condition!=='Good condition')&&!d.reason.trim()){toast('Add a reason for the discrepancy.');return}const receipt=INDENTS.find(r=>r.id==='IND-0247');if(receipt.receiptRecorded){toast('This sample handover already has a receipt.');return}receipt.received=n+' units';receipt.status=n===36&&d.condition==='Good condition'?'Received':'Partially received';receipt.receiptRecorded=true;receipt.receiptNote=d.reason;$('#modal').close();render();toast('Sample floor receipt recorded.');}else if(f.id==='payment-form'){const total=state.basket.reduce((a,r)=>a+r.qty*r.amount,0),paid=Number(d.cash);if(paid<total){$('#payment-error').textContent='Cash received is less than the amount due. The practice bill is still open.';return}state.basket=[];state.customer='';openModal('Practice sale complete',`<div class="empty-state" style="padding:15px 0">${icon('circle-check')}<h3>BILL-DEMO-0148</h3><p>Sale total: ${money(total)}</p><p>Cash received: ${money(paid)}</p><div class="basket-total"><span>Change</span><span>${money(paid-total)}</span></div><p class="form-hint">Preview complete. No real payment or ERP stock change occurred.</p></div>`,button('Start next bill','close-modal',true,'plus'));render();}else if(f.id==='cash-form'){CASH[2].counted=Number(d.count);const v=CASH[2].counted-CASH[2].expected;CASH[2].status=v===0?'Balanced':(v<0?'Short':'Over')+' · '+money(Math.abs(v));$('#modal').close();render();toast('Blind count submitted in this preview.');}else if(f.id==='note-form'){const {kind,id}=state.currentDetail,key=kind+':'+id;(state.recordNotes[key]??=[]).push(d.note);$('#modal').close();showDetail(kind,id);toast('Note added to this record in the current preview.');}else if(f.id==='customer-form'){state.customer=d.name;$('#modal').close();render();toast('Sample customer added to the current practice bill.');}});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='k'){e.preventDefault();searchDialog()}if(e.key==='Escape'){$('#app').classList.remove('menu-open');$('#mobile-shade').classList.remove('visible')}});
document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
enhance();const initial=location.hash.slice(1);navigate(initial&&moduleById(initial.split('/')[0])?initial:'overview/dashboard');
